import numpy as np
import pandas as pd
import math

def generate_signals(df: pd.DataFrame) -> pd.Series:
    n = 12
    warm_up = n - 1

    df['SMA'] = df['close'].rolling(n).mean()

    signals = pd.Series(0, index=df.index)

    for i in range(warm_up, len(df)):
        if i == warm_up:
            if df['close'][i] > df['SMA'][i]:
                signals[i] = 1
            elif df['close'][i] < df['SMA'][i]:
                signals[i] = -1
        else:
            if signals[i-1] == 0:
                if df['close'][i] > df['SMA'][i]:
                    signals[i] = 1
                elif df['close'][i] < df['SMA'][i]:
                    signals[i] = -1
            elif signals[i-1] == 1:
                if df['close'][i] < df['SMA'][i]:
                    signals[i] = 0
                else:
                    signals[i] = signals[i-1]
            elif signals[i-1] == -1:
                if df['close'][i] > df['SMA'][i]:
                    signals[i] = 0
                else:
                    signals[i] = signals[i-1]

    # Apply trailing stop
    signals = signals.where(signals != 0)
    signals = signals.where((signals == 1) & (df['close'] < df['peak'].shift(1) * (1 - 0.05)) | (signals == 1))
    signals = signals.where((signals == -1) & (df['close'] > df['trough'].shift(1) * (1 + 0.05)) | (signals == -1))

    # Fill NaNs with 0
    signals = signals.fillna(0)

    return signals
